export function SettingsRecordingsSection() {
  const syncSettings = useProfilesStore(selectSyncSettings);
  const handwritingStatusMessage = useHandwritingStore((state) => state.statusMessage);
  const handwritingQueue = useHandwritingStore((state) => state.queue);
  const handwritingJobs = useHandwritingStore((state) => state.jobs);
  const handwritingBusy = useHandwritingStore((state) => state.listBusy);
  const handwritingError = useHandwritingStore((state) => state.listError);

  const isLocal = syncSettings.handwritingOcrProvider === "local";
  const isHuggingFace = syncSettings.handwritingOcrProvider === "huggingface";
  const providerKey = isHuggingFace
    ? syncSettings.huggingFaceApiKey
    : syncSettings.openAiApiKey;
  const providerModel = isHuggingFace
    ? syncSettings.huggingFaceModel
    : syncSettings.openAiModel;

  useEffect(() => {
    void refreshHandwritingJobs();
  }, [refreshHandwritingJobs]);

  return (
    <SettingsSection
      title="Recordings"
      description="Mobile voice transcription and handwriting OCR settings. For desktop voice transcription, see the Transcription section."
    >
      <SettingsCard
        title="Voice transcription (mobile)"
        description="Mobile uses AssemblyAI cloud transcription."
      >
        <SettingsField label="AssemblyAI API key">
          <Input
            type="password"
            value={syncSettings.assemblyAiApiKey}
            onChange={(event) => updateSyncSettings({ assemblyAiApiKey: event.target.value })}
            placeholder="Paste AssemblyAI key (mobile only)"
            autoCapitalize="off"
            autoCorrect="off"
          />
        </SettingsField>
        <label className="inline-flex items-center gap-2 text-sm text-foreground">
          <input
            type="checkbox"
            className="h-4 w-4 rounded border-border"
            checked={syncSettings.mobileAutoTranscriptionEnabled}
            onChange={(event) =>
              updateSyncSettings({ mobileAutoTranscriptionEnabled: event.target.checked })
            }
          />
          <span>Auto-queue voice transcription on mobile</span>
        </label>
      </SettingsCard>

      <SettingsCard title="Handwriting OCR">
        <SettingsField label="Provider">
          <SettingsSelect
            value={syncSettings.handwritingOcrProvider}
            onChange={(event) =>
              updateSyncSettings({
                handwritingOcrProvider: event.target.value as
                  | "local"
                  | "openai"
                  | "huggingface",
              })
            }
          >
            <option value="local">Local (EasyOCR)</option>
            <option value="openai">OpenAI Vision</option>
            <option value="huggingface">Hugging Face</option>
          </SettingsSelect>
        </SettingsField>
        {!isLocal ? (
          <>
            <SettingsField label={isHuggingFace ? "Hugging Face API key" : "OpenAI API key"}>
              <Input
                type="password"
                value={providerKey}
                onChange={(event) =>
                  updateSyncSettings(
                    isHuggingFace
                      ? { huggingFaceApiKey: event.target.value }
                      : { openAiApiKey: event.target.value }
                  )
                }
                placeholder={isHuggingFace ? "Paste Hugging Face key" : "Paste OpenAI key"}
                autoCapitalize="off"
                autoCorrect="off"
              />
            </SettingsField>
            <SettingsField label={isHuggingFace ? "Model ID" : "Model"}>
              <Input
                type="text"
                value={providerModel}
                onChange={(event) =>
                  updateSyncSettings(
                    isHuggingFace
                      ? { huggingFaceModel: event.target.value }
                      : { openAiModel: event.target.value }
                  )
                }
                placeholder={
                  isHuggingFace ? "microsoft/trocr-base-handwritten" : "gpt-4.1-mini"
                }
                autoCapitalize="off"
                autoCorrect="off"
              />
            </SettingsField>
          </>
        ) : (
          <SettingsHelpText>
            Photos stay pending on mobile. This desktop recognizes them after sync.
          </SettingsHelpText>
        )}
      </SettingsCard>

      {isLocal ? (
        <LocalOcrEngineCard
          modelPath={syncSettings.localOcrModelPath}
          onModelPathChange={(value) => void updateSyncSettings({ localOcrModelPath: value })}
        />
      ) : null}

      <SettingsCard title="Handwriting jobs">
        <SettingsInfoGrid>
          <SettingsInfoRow label="Queue in-flight">
            <code className="text-xs">{handwritingQueue?.in_flight ?? 0}</code>
          </SettingsInfoRow>
          <SettingsInfoRow label="Queue active job">
            <code className="text-xs">{handwritingQueue?.current_note ?? "-"}</code>
          </SettingsInfoRow>
        </SettingsInfoGrid>
        {handwritingStatusMessage ? (
          <SettingsHelpText>{handwritingStatusMessage}</SettingsHelpText>
        ) : null}
        <SettingsActionRow>
          <Button
            variant="secondary"
            size="sm"
            type="button"
            onClick={() => void refreshHandwritingJobs()}
            disabled={handwritingBusy}
          >
            {handwritingBusy ? "Refreshing..." : "Refresh handwriting queue"}
          </Button>
        </SettingsActionRow>
        {handwritingError ? <SettingsErrorText>{handwritingError}</SettingsErrorText> : null}
      </SettingsCard>

      <SettingsCard title="Handwriting queue items">
        <SettingsInfoGrid>
          {handwritingJobs.length === 0 ? (
            <div className="px-3 py-2 text-xs text-muted-foreground">
              No handwriting OCR jobs yet.
            </div>
          ) : (
            handwritingJobs.map((item) => (
              <div
                key={item.note_path}
                className="grid gap-1 border-b border-border/50 px-3 py-2.5 last:border-b-0"
              >
                <div className="break-all text-sm font-medium text-foreground">{item.note_path}</div>
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                  <code>{formatHandwritingStatus(item)}</code>
                  <span>updated {formatUpdatedAt(item.updated_ms)}</span>
                </div>
                {item.error ? <SettingsErrorText>{item.error}</SettingsErrorText> : null}
              </div>
            ))
          )}
        </SettingsInfoGrid>
      </SettingsCard>
    </SettingsSection>
  );
}

HANDWRITING MAIN VERSION
import {
  createContext,
  useCallback,
  useContext,
  useRef,
  useState,
  type ReactNode,
} from "react";
import * as api from "../api/handwriting-api";
import type {
  HandwritingOcrListItem,
  HandwritingOcrQueueSnapshot,
} from "@typenotes/shared/types";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { toBase64 } from "@/shared/lib/notes";
import { useProfiles } from "@/features/profiles/hooks/profiles-context";
import { useAutoQueueLoop } from "@/features/processing/hooks/use-auto-queue-loop";
import { useProcessingQueue } from "@/features/processing/hooks/use-processing-queue";
import { jobListSignature } from "@typenotes/shared/jobs";
import { getErrorMessage } from "@typenotes/shared/errors";

type HandwritingContextValue = {
  handwritingImportBusy: boolean;
  handwritingStatusMessage: string | null;
  handwritingQueueBusy: boolean;
  handwritingQueue: HandwritingOcrQueueSnapshot | null;
  handwritingJobs: HandwritingOcrListItem[];
  handwritingBusy: boolean;
  handwritingError: string | null;
  importHandwritingFile: (
    file: File,
    preferredFolderPath?: string | null
  ) => Promise<void>;
  refreshHandwritingJobs: () => Promise<void>;
  queueHandwritingOcr: (trigger?: "manual" | "auto") => Promise<void>;
};

const HandwritingContext = createContext<HandwritingContextValue | null>(null);

export function HandwritingProvider({
  children,
  activeFolder,
  onHandwritingComplete,
}: {
  children: ReactNode;
  activeFolder: string;
  onHandwritingComplete: (result: {
    folder_path: string;
    note_path: string;
    attachment_path: string;
  }) => Promise<void>;
}) {
  const { syncSettings } = useProfiles();
  const [handwritingImportBusy, setHandwritingImportBusy] = useState(false);
  const [handwritingStatusMessage, setHandwritingStatusMessage] = useState<string | null>(null);
  const [handwritingQueueBusy, setHandwritingQueueBusy] = useState(false);
  const queueBusyRef = useRef(false);

  const resolveTargetFolder = useCallback(
    (preferredFolderPath?: string | null) => {
      const preferred = preferredFolderPath?.trim();
      if (preferred) {
        return preferred;
      }
      const active = activeFolder.trim();
      return active || FEED_FOLDER_PATH;
    },
    [activeFolder]
  );

  const getProviderConfig = useCallback(() => {
    if (syncSettings.handwritingOcrProvider === "local") {
      return {
        provider: "local" as const,
        apiKey: "",
        model: "",
        modelPath: syncSettings.localOcrModelPath.trim(),
      };
    }
    if (syncSettings.handwritingOcrProvider === "huggingface") {
      return {
        provider: "huggingface" as const,
        apiKey: syncSettings.huggingFaceApiKey.trim(),
        model: syncSettings.huggingFaceModel.trim(),
        modelPath: "",
      };
    }
    return {
      provider: "openai" as const,
      apiKey: syncSettings.openAiApiKey.trim(),
      model: syncSettings.openAiModel.trim(),
      modelPath: "",
    };
  }, [
    syncSettings.handwritingOcrProvider,
    syncSettings.localOcrModelPath,
    syncSettings.huggingFaceApiKey,
    syncSettings.huggingFaceModel,
    syncSettings.openAiApiKey,
    syncSettings.openAiModel,
  ]);

  const loadHandwritingSnapshot = useCallback(async () => {
    const snapshot = await api.listHandwritingOcrJobs();
    return {
      queue: snapshot.queue,
      items: snapshot.jobs,
    };
  }, []);

  const {
    queue: handwritingQueue,
    items: handwritingJobs,
    busy: handwritingBusy,
    error: handwritingError,
    refresh: refreshHandwritingJobs,
  } = useProcessingQueue<HandwritingOcrQueueSnapshot, HandwritingOcrListItem>({
    loadSnapshot: loadHandwritingSnapshot,
    getSignature: jobListSignature,
    invalidateEventName: "note-previews-invalidated",
    refreshOnMount: true,
  });

  const queueHandwritingOcr = useCallback(
    async (trigger: "manual" | "auto" = "manual") => {
      if (queueBusyRef.current) {
        return;
      }
      const config = getProviderConfig();
      if (config.provider !== "local" && !config.apiKey) {
        if (trigger === "manual") {
          setHandwritingStatusMessage("OCR API key is required.");
        }
        return;
      }
      if (config.provider !== "local" && !config.model) {
        if (trigger === "manual") {
          setHandwritingStatusMessage("OCR model is required.");
        }
        return;
      }

      queueBusyRef.current = true;
      setHandwritingQueueBusy(true);
      try {
        const result = await api.queueHandwritingOcr(
          config.provider,
          config.apiKey,
          config.model,
          config.modelPath
        );
        const label =
          trigger === "manual"
            ? `Scanned ${result.scanned}, queued ${result.queued}, in-flight ${result.in_flight}.`
            : `Auto queue: scanned ${result.scanned}, queued ${result.queued}.`;
        setHandwritingStatusMessage(label);
      } catch (error) {
        const message = getErrorMessage(error);
        setHandwritingStatusMessage(message);
      } finally {
        queueBusyRef.current = false;
        setHandwritingQueueBusy(false);
        void refreshHandwritingJobs();
      }
    },
    [getProviderConfig, refreshHandwritingJobs]
  );

  const importHandwritingFile = useCallback(
    async (file: File, preferredFolderPath?: string | null) => {
      setHandwritingImportBusy(true);
      try {
        const bytes = new Uint8Array(await file.arrayBuffer());
        const result = await api.saveHandwritingAttachment(
          toBase64(bytes),
          file.type || undefined,
          file.name || undefined,
          resolveTargetFolder(preferredFolderPath),
          syncSettings.noteFileNameFormat
        );
        await onHandwritingComplete(result);
        setHandwritingStatusMessage(`Saved ${result.note_path}.`);
        void refreshHandwritingJobs();
        await queueHandwritingOcr("auto");
      } catch (error) {
        const message = getErrorMessage(error);
        setHandwritingStatusMessage(message);
        throw error;
      } finally {
        setHandwritingImportBusy(false);
      }
    },
    [
      onHandwritingComplete,
      queueHandwritingOcr,
      refreshHandwritingJobs,
      resolveTargetFolder,
      syncSettings.noteFileNameFormat,
    ]
  );

  const autoQueueConfig = getProviderConfig();
  const autoQueueHandwriting = useCallback(
    () => queueHandwritingOcr("auto"),
    [queueHandwritingOcr]
  );
  useAutoQueueLoop({
    enabled:
      autoQueueConfig.provider === "local" ||
      (autoQueueConfig.apiKey.length > 0 && autoQueueConfig.model.length > 0),
    delayMs: 0,
    onTick: autoQueueHandwriting,
  });

  return (
    <HandwritingContext.Provider
      value={{
        handwritingImportBusy,
        handwritingStatusMessage,
        handwritingQueueBusy,
        handwritingQueue,
        handwritingJobs,
        handwritingBusy,
        handwritingError,
        importHandwritingFile,
        refreshHandwritingJobs,
        queueHandwritingOcr,
      }}
    >
      {children}
    </HandwritingContext.Provider>
  );
}

export function useHandwriting() {
  const context = useContext(HandwritingContext);
  if (!context) {
    throw new Error("useHandwriting must be used within a HandwritingProvider");
  }
  return context;
}

LEGACY MIGRATION MAIN VERSION
import { useEffect } from "react";

import * as api from "@/features/profiles/api/profiles-api";
import { LEGACY_PROFILE_SYNC_STORAGE_KEYS } from "@/features/profiles/lib/profile-sync-settings";
import { PROFILE_SYNC_STORAGE_KEY } from "@/shared/constants";
import {
  getProfileSyncSettings,
  readProfileSyncStore,
} from "@/shared/lib/storage";
import type { NotesProfileSnapshot } from "@typenotes/shared/types";

type UseLegacyProfileSyncMigrationArgs = {
  profilesSnapshot: NotesProfileSnapshot | null;
  profilesBusy: boolean;
  activeProfileId: string | null;
  profiles: NotesProfileSnapshot["profiles"];
  refreshProfiles: () => Promise<NotesProfileSnapshot>;
  setProfilesBusy: (busy: boolean) => void;
};

export function useLegacyProfileSyncMigration({
  profilesSnapshot,
  profilesBusy,
  activeProfileId,
  profiles,
  refreshProfiles,
  setProfilesBusy,
}: UseLegacyProfileSyncMigrationArgs) {
  useEffect(() => {
    if (!profilesSnapshot || profilesBusy) return;

    const store = readProfileSyncStore();
    if (Object.keys(store).length === 0) return;

    const migrate = async () => {
      setProfilesBusy(true);
      try {
        // Old builds stored one mixed settings blob in localStorage. The backend
        // now keeps app-wide provider settings separately from per-profile git
        // settings, so migrate the first app config and then each profile.
        const firstProfileId = activeProfileId || Object.keys(store)[0];
        const firstSettings = getProfileSyncSettings(firstProfileId);

        await api.updateAppConfig({
          assemblyai_api_key: firstSettings.assemblyAiApiKey,
          whisper_model: firstSettings.whisperModel,
          handwriting_ocr_provider: firstSettings.handwritingOcrProvider,
          local_ocr_model_path: firstSettings.localOcrModelPath,
          openai_api_key: firstSettings.openAiApiKey,
          openai_model: firstSettings.openAiModel,
          huggingface_api_key: firstSettings.huggingFaceApiKey,
          huggingface_model: firstSettings.huggingFaceModel,
          note_file_name_format: firstSettings.noteFileNameFormat,
        });

        for (const profile of profiles) {
          const settings = store[profile.id];
          if (settings) {
            await api.updateProfileSettings(profile.id, {
              git_remote_url: settings.gitRemoteUrl ?? "",
              git_branch: settings.gitBranch ?? "main",
              git_username: settings.gitUsername ?? "",
              git_password: settings.gitPassword ?? "",
              git_commit_message: settings.gitCommitMessage ?? "Sync notes",
              git_trusted_ssh_host: "",
              git_trusted_ssh_host_key_sha256: "",
              mobile_auto_transcription_enabled:
                settings.mobileAutoTranscriptionEnabled ?? true,
              mobile_auto_handwriting_ocr_enabled:
                settings.mobileAutoHandwritingOcrEnabled ?? true,
            });
          }
        }

        window.localStorage.removeItem(PROFILE_SYNC_STORAGE_KEY);
        LEGACY_PROFILE_SYNC_STORAGE_KEYS.forEach((key) =>
          window.localStorage.removeItem(key)
        );

        await refreshProfiles();
      } catch (error) {
        console.error("Profile sync settings migration failed", error);
      } finally {
        setProfilesBusy(false);
      }
    };

    void migrate();
  }, [
    activeProfileId,
    profiles,
    profilesBusy,
    profilesSnapshot,
    refreshProfiles,
    setProfilesBusy,
  ]);
}

