    }
  }, [modelPath]);

  useEffect(() => {
    void probe();
  }, [probe]);

  const setUp = async () => {
    setSettingUp(true);
    try {
      setStatus(await api.checkLocalOcrStatus(modelPath.trim() || undefined, true));
    } catch (error) {
      setStatus({
        available: false,
        python_found: false,
        model_path: modelPath,
        error: getErrorMessage(error),
      });
    } finally {
      setSettingUp(false);
    }
  };

